function render({width,state,params}) {
  const w = Number.isFinite(width) ? Math.max(320, Math.min(760, width)) : 480;
  const requested = typeof state === 'string' ? state : state && state.key;
  const phase = ['local','sum','broadcast'].includes(requested) ? requested : 'local';
  const initial = [[1,1],[2,2]];
  const total = initial[0].map((v,j) => v + initial[1][j]);
  const current = phase === 'local' ? initial.map(v => v.slice()) : phase === 'sum' ? [total.slice(), initial[1].slice()] : [total.slice(),total.slice()];
  const bg = '#faf8f2', ink = '#292824', blue = '#356c98', orange = '#ba682e', quiet = '#d8d4ca';
  const narrow = w < 440;
  const boxW = narrow ? 80 : 104;
  const leftX = narrow ? 68 : w * 0.25;
  const rightX = narrow ? w - 112 : w * 0.70;
  const rows = [76,146];
  const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  const text = (x,y,s,color=ink,size=15,anchor='middle') => '<text x="'+x+'" y="'+y+'" fill="'+color+'" font-size="'+size+'" text-anchor="'+anchor+'">'+esc(s)+'</text>';
  function vector(x,y,values,color) {
    return '<rect x="'+x+'" y="'+(y-21)+'" width="'+boxW+'" height="38" rx="3" fill="'+bg+'" stroke="'+color+'"/><line x1="'+(x+boxW/2)+'" y1="'+(y-21)+'" x2="'+(x+boxW/2)+'" y2="'+(y+17)+'" stroke="'+quiet+'"/>'+values.map((v,j)=>text(x+boxW*(j+0.5)/2,y+4,v,color,17)).join('');
  }
  let body = text(leftX+boxW/2,29,'初值 · 1×2') + text(rightX+boxW/2,29,'当前值');
  rows.forEach((y,i) => {
    body += text(16,y+4,'GPU'+i,ink,14,'start');
    body += vector(leftX,y,initial[i],blue);
    const isTotal = phase === 'broadcast' || (phase === 'sum' && i === 0);
    body += vector(rightX,y,current[i],isTotal ? orange : blue);
  });
  const mid = (leftX+boxW+rightX)/2;
  if (phase === 'sum') {
    body += '<path d="M '+(leftX+boxW)+' '+rows[1]+' C '+mid+' '+rows[1]+', '+mid+' '+rows[0]+', '+(rightX-5)+' '+rows[0]+'" fill="none" stroke="'+orange+'" stroke-width="2" marker-end="url(#ar)"/>';
  }
  if (phase === 'broadcast') {
    const edge = Math.min(w-9,rightX+boxW+24);
    body += '<path d="M '+(rightX+boxW)+' '+rows[0]+' H '+edge+' V '+rows[1]+' H '+(rightX+boxW+5)+'" fill="none" stroke="'+orange+'" stroke-width="2" marker-end="url(#ar)"/>';
  }
  const operation = phase === 'local' ? 'data[0], data[1]' : phase === 'sum' ? 'data[0] += data[1]' : 'data[1] = data[0]';
  body += text(w/2,195,operation,ink,15);
  body += text(w/2,222,'[1, 1] + [2, 2] = [3, 3]',orange,16);
  const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="'+w+'" height="240" viewBox="0 0 '+w+' 240" role="img"><title>求和，再广播</title><desc>'+esc('阶段：'+phase+'。GPU0当前向量为'+current[0].join(',')+'；GPU1当前向量为'+current[1].join(',')+'。左列始终保留初值。')+'</desc><defs><marker id="ar" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="6" markerHeight="6" orient="auto"><path d="M 0 0 L 8 4 L 0 8 Z" fill="'+orange+'"/></marker></defs><rect width="'+w+'" height="240" fill="'+bg+'"/><g font-family="sans-serif">'+body+'</g></svg>';
  return {svg, facts:{phase, initial, tensorShapes:[[1,2],[1,2]], sum:total, current, operation, updateSteps:[{target:0,operation:'add',source:1,result:total.slice()},{target:1,operation:'copy',source:0,result:total.slice()}], completedSteps:phase==='local'?0:phase==='sum'?1:2, geometry:{width:w,height:240,narrow,boxWidth:boxW,initialX:leftX,currentX:rightX,rowCenters:rows}}};
}

function render({width,state,params}) {
  const w = Number.isFinite(width) ? Math.max(320,Math.min(760,width)) : 480;
  const p = params || {};
  const k = Number.isFinite(p.gpus) ? Math.max(1,Math.min(4,Math.round(p.gpus))) : 2;
  const gradients = [-2,-1,0,1,2,3,-2,-1,0,1,2,3];
  const B = gradients.length, n = B/k, theta = 1, lr = 0.2;
  const shards = Array.from({length:k},(_,i) => {
    const start = i*n;
    const values = gradients.slice(start,start+n);
    return {gpu:i,start,endExclusive:start+n,count:values.length,gradients:values,localGradientSum:values.reduce((a,b)=>a+b,0)};
  });
  const sum = shards.reduce((a,s)=>a+s.localGradientSum,0);
  const mean = sum/B, updated = theta-lr*mean;
  const bg = '#faf8f2', ink = '#292824', blue = '#356c98', orange = '#ba682e', quiet = '#d8d4ca';
  const narrow = w < 440;
  const gridW = Math.min(w-32,600), gridX = (w-gridW)/2, cellW = gridW/B;
  const rowTop = 128, rowH = 34, footerY = rowTop+k*rowH+15, h = footerY+53;
  const f = v => Number(v.toFixed(4)).toString();
  const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  const text = (x,y,s,color=ink,size=15,anchor='middle') => '<text x="'+x+'" y="'+y+'" fill="'+color+'" font-size="'+size+'" text-anchor="'+anchor+'">'+esc(s)+'</text>';
  let body = text(w/2,23,'手选梯度；θ=1，η=0.2',ink,14);
  gradients.forEach((g,j) => {
    body += '<rect x="'+(gridX+j*cellW)+'" y="39" width="'+cellW+'" height="30" fill="'+bg+'" stroke="'+quiet+'"/>';
    body += text(gridX+(j+0.5)*cellW,59,g,blue,14);
  });
  shards.forEach(s => {
    const x = gridX+s.start*cellW+2, end = gridX+s.endExclusive*cellW-2;
    body += '<path d="M '+x+' 73 V 78 H '+end+' V 73" fill="none" stroke="'+blue+'" stroke-width="1.5"/>';
    body += text((x+end)/2,96,'GPU'+s.gpu,blue,14);
  });
  const xs = narrow ? [16,w*0.30,w*0.51,w*0.80] : [gridX,gridX+gridW*0.26,gridX+gridW*0.49,gridX+gridW*0.80];
  body += text(xs[0],118,'设备',ink,14,'start') + text(xs[1],118,'样本数',ink,14) + text(xs[2],118,'局部Σg',ink,14) + text(xs[3],118,'θ → θ′',ink,14);
  shards.forEach((s,i) => {
    const y = rowTop+i*rowH+19;
    body += text(xs[0],y,'GPU'+s.gpu,ink,14,'start') + text(xs[1],y,s.count,blue,16) + text(xs[2],y,s.localGradientSum,blue,16) + text(xs[3],y,f(theta)+' → '+f(updated),orange,16);
    body += '<line x1="16" y1="'+(y+9)+'" x2="'+(w-16)+'" y2="'+(y+9)+'" stroke="'+quiet+'"/>';
  });
  body += text(w/2,footerY,'Σg = '+sum+'；'+sum+' / '+B+' = '+f(mean),orange,16);
  body += text(w/2,footerY+28,'θ′ = '+theta+' − '+lr+' × '+f(mean)+' = '+f(updated),orange,16);
  const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="'+w+'" height="'+h+'" viewBox="0 0 '+w+' '+h+'" role="img"><title>求和后除以全批量</title><desc>'+esc('固定十二个手选样本梯度，分配到'+k+'个GPU，每个GPU处理'+n+'个样本。聚合梯度和为'+sum+'，全批量平均梯度为'+mean+'，所有副本更新到'+updated+'。')+'</desc><rect width="'+w+'" height="'+h+'" fill="'+bg+'"/><g font-family="sans-serif">'+body+'</g></svg>';
  return {svg, facts:{phase:'normalize',exampleType:'手选单参数平方损失示例',lossDefinition:'L_i(theta) = (theta - a_i)^2 / 2',sampleTargets:gradients.map(g=>theta-g),perSampleGradients:gradients,batchSize:B,gpuCount:k,shards,initialParameter:theta,learningRate:lr,aggregateGradientSum:sum,normalizationDenominator:B,meanGradient:mean,updatedParameters:Array(k).fill(updated),updateSteps:[{operation:'sum local sample losses and differentiate',localGradientSums:shards.map(s=>s.localGradientSum)},{operation:'allreduce sum and broadcast',gradientOnEachGPU:Array(k).fill(sum)},{operation:'divide by global batch size and apply SGD',denominator:B,delta:lr*mean,result:updated}],geometry:{width:w,height:h,narrow,gridX,gridWidth:gridW,cellWidth:cellW,columnXs:xs,rowHeight:rowH}}};
}
